document.addEventListener('DOMContentLoaded', async () => {
    console.log('🚀 Inicializando PWA Vistorias Imobiliárias v1.0.0');
    
    // Inicializar IndexedDB
    await inicializarIndexedDB();
    
    // Registrar Service Worker
    if ('serviceWorker' in navigator) {
        try {
            await navigator.serviceWorker.register('/sw.js');
            console.log('✅ Service Worker registrado');
        } catch (err) {
            console.error('❌ Erro ao registrar Service Worker:', err);
        }
    }
    
    // Solicitar armazenamento persistente
    if (navigator.storage && navigator.storage.persist) {
        const granted = await navigator.storage.persist();
        console.log(granted ? '✅ Armazenamento persistente concedido' : '⚠️ Armazenamento não persistente');
    }
    
    // Mostrar tela de PIN
    mostrarTelaPIN();
    
    // Listeners de formulário
    configurarListeners();
    
    // Monitoramento de bateria
    if ('getBattery' in navigator) {
        const battery = await navigator.getBattery();
        atualizarIndicadorBateria(battery);
        battery.addEventListener('levelchange', () => atualizarIndicadorBateria(battery));
    }
    
    // Limpeza automática de vistorias antigas
    await limparVistoriasAntigas();
    
    // Verificar espaço disponível
    setInterval(verificarEspacoDisponivel, 60000);
    
    console.log('✅ App inicializado com sucesso');
});

// ============================================================
// INDEXEDDB - PERSISTÊNCIA
// ============================================================

async function inicializarIndexedDB() {
    return new Promise((resolve, reject) => {
        const request = indexedDB.open('vistorias-db', 1);
        
        request.onerror = () => reject('Erro ao abrir IndexedDB');
        
        request.onsuccess = (event) => {
            db = event.target.result;
            console.log('✅ IndexedDB inicializado');
            resolve();
        };
        
        request.onupgradeneeded = (event) => {
            const database = event.target.result;
            
            // Store de rascunhos
            if (!database.objectStoreNames.contains('rascunhos')) {
                database.createObjectStore('rascunhos', { keyPath: 'id' });
            }
            
            // Store de vistorias finalizadas
            if (!database.objectStoreNames.contains('finalizadas')) {
                database.createObjectStore('finalizadas', { keyPath: 'id' });
            }
            
            // Store de fotos
            if (!database.objectStoreNames.contains('fotos')) {
                database.createObjectStore('fotos', { keyPath: 'id' });
            }
            
            console.log('✅ Stores criados no IndexedDB');
        };
    });
}

async function salvarRascunho() {
    if (!db || !vistoriaAtual.id) return;
    
    const rascunho = {
        id: vistoriaAtual.id,
        timestamp: Date.now(),
        checkin: vistoriaAtual.checkin,
        secao1: obterDadosSecao1(),
        blocos: vistoriaAtual.blocos,
        fotos: vistoriaAtual.fotos.map(f => f.id),
        assinaturas: vistoriaAtual.assinaturas,
        adicionais: obterAdicionais()
    };
    
    const transaction = db.transaction(['rascunhos'], 'readwrite');
    const store = transaction.objectStore('rascunhos');
    await store.put(rascunho);
    
    console.log('💾 Rascunho salvo:', new Date().toLocaleTimeString());
}

async function salvarFoto(fotoData) {
    const transaction = db.transaction(['fotos'], 'readwrite');
    const store = transaction.objectStore('fotos');
    await store.put(fotoData);
}

async function limparVistoriasAntigas() {
    try {
        const transaction = db.transaction(['finalizadas'], 'readwrite');
        const store = transaction.objectStore('finalizadas');
        const vistorias = await store.getAll();
        
        const seteDiasAtras = Date.now() - (7 * 24 * 60 * 60 * 1000);
        
        for (const v of vistorias) {
            if (v.timestamp < seteDiasAtras) {
                await store.delete(v.id);
                console.log(`🗑️ Vistoria ${v.endereco} removida (>7 dias)`);
            }
        }
    } catch (err) {
        console.error('Erro ao limpar vistorias antigas:', err);
    }
}

