function mostrarTelaPIN() {
    document.getElementById('lock-screen').style.display = 'flex';
    document.getElementById('pin-input').focus();
    
    document.getElementById('pin-input').addEventListener('keypress', (e) => {
        if (e.key === 'Enter') validarPIN();
    });
}

function validarPIN() {
    const pinInput = document.getElementById('pin-input').value;
    
    if (pinInput === CONFIG.PIN_CORRETO) {
        document.getElementById('lock-screen').style.display = 'none';
        mostrarTelaCheckin();
    } else {
        alert('❌ PIN incorreto!');
        document.getElementById('pin-input').value = '';
        document.getElementById('pin-input').focus();
    }
}

function mostrarTelaCheckin() {
    document.getElementById('checkin-screen').style.display = 'block';
}

async function fazerCheckin() {
    const statusDiv = document.getElementById('checkin-status');
    statusDiv.innerHTML = '<p>📍 Obtendo localização GPS...</p>';
    
    try {
        const gps = await obterGPSValidado();
        
        if (!gps) {
            alert('❌ GPS inválido ou indisponível');
            return;
        }
        
        vistoriaAtual.id = Date.now();
        vistoriaAtual.checkin = {
            timestamp: Date.now(),
            gps: gps,
            horario: new Date().toLocaleTimeString('pt-BR')
        };
        
        // Detectar vistoria noturna
        const hora = new Date().getHours();
        const isNoturno = hora >= 18 || hora < 8;
        if (isNoturno) {
            document.getElementById('add-noturno').checked = true;
        }
        
        statusDiv.innerHTML = `
            <p style="color: green;">✅ CHECK-IN REALIZADO</p>
            <p>📍 GPS: ${gps.lat.toFixed(6)}, ${gps.lng.toFixed(6)}</p>
            <p>⏰ Horário: ${vistoriaAtual.checkin.horario}</p>
            ${isNoturno ? '<p>🌙 Vistoria Noturna Detectada (+30%)</p>' : ''}
        `;
        
        setTimeout(() => {
            document.getElementById('checkin-screen').style.display = 'none';
            document.getElementById('main-form').style.display = 'block';
        }, 2000);
        
    } catch (err) {
        statusDiv.innerHTML = `<p style="color: red;">❌ Erro: ${err.message}</p>`;
    }
}

async function obterGPSValidado() {
    const tentativas = [];
    
    for (let i = 0; i < CONFIG.GPS_TENTATIVAS; i++) {
        try {
            const pos = await new Promise((resolve, reject) => {
                navigator.geolocation.getCurrentPosition(
                    resolve,
                    reject,
                    {
                        enableHighAccuracy: true,
                        timeout: CONFIG.GPS_TIMEOUT,
                        maximumAge: 0
                    }
                );
            });
            
            tentativas.push({
                lat: pos.coords.latitude,
                lng: pos.coords.longitude,
                accuracy: pos.coords.accuracy
            });
            
            await new Promise(r => setTimeout(r, 1000));
        } catch (e) {
            console.warn('Tentativa GPS falhou:', e);
        }
    }
    
    if (tentativas.length === 0) {
        throw new Error('GPS indisponível');
    }
    
    // Validação geográfica (Brasil)
    for (const t of tentativas) {
        if (t.lat < -33 || t.lat > 5 || t.lng < -73 || t.lng > -34) {
            alert('⚠️ GPS COM ERRO!\n\nCoordenadas fora do Brasil detectadas.');
            return null;
        }
    }
    
    // Mediana das leituras
    const lats = tentativas.map(t => t.lat).sort((a, b) => a - b);
    const lngs = tentativas.map(t => t.lng).sort((a, b) => a - b);
    
    return {
        lat: lats[Math.floor(lats.length / 2)],
        lng: lngs[Math.floor(lngs.length / 2)],
        accuracy: Math.min(...tentativas.map(t => t.accuracy)),
        timestamp: Date.now()
    };
}

