// CONFIGURAÇÃO DE LISTENERS DO FORMULÁRIO
// ============================================================

function configurarListeners() {
    // Contador de caracteres para 1b
    const campo1b = document.getElementById('campo-1b');
    campo1b.addEventListener('input', (e) => {
        const contador = e.target.nextElementSibling;
        contador.textContent = `${e.target.value.length} / 150`;
    });
    
    // Mudança em 1c (Tipo de Imóvel) - altera 1d e 1f
    const campo1c = document.getElementById('campo-1c');
    campo1c.addEventListener('change', (e) => {
        const tipo = e.target.value;
        atualizarTipologias(tipo);
        atualizarFaixasMetragem(tipo);
        atualizarSecao2(tipo);
    });
    
    // Salvamento automático com debounce
    let debounceTimer;
    document.getElementById('formulario-vistoria').addEventListener('input', () => {
        clearTimeout(debounceTimer);
        debounceTimer = setTimeout(() => salvarRascunho(), 500);
    });
    
    // Botão SOS
    document.getElementById('btn-sos').addEventListener('click', ativarSOS);
}

function atualizarTipologias(tipo) {
    const datalist = document.getElementById('lista-1d');
    datalist.innerHTML = '';
    
    if (TIPOLOGIAS[tipo]) {
        TIPOLOGIAS[tipo].forEach(tip => {
            const option = document.createElement('option');
            option.value = tip;
            datalist.appendChild(option);
        });
    }
}

