function mostrarSugestoesRapidas(blocoId, observacao) {
    const container = document.getElementById(`${blocoId}-sugestoes`);
    container.innerHTML = '';
    
    if (SUGESTOES_RAPIDAS[observacao]) {
        const sugestoes = SUGESTOES_RAPIDAS[observacao];
        sugestoes.forEach(sug => {
            const chip = document.createElement('button');
            chip.type = 'button';
            chip.className = 'btn-chip';
            chip.textContent = sug;
            chip.style.cssText = 'margin: 0.25rem; padding: 0.5rem 1rem; background: #E5E5E5; border: none; border-radius: 20px; cursor: pointer; font-size: 0.875rem;';
            chip.addEventListener('click', () => {
                const textarea = document.getElementById(`${blocoId}-detalhes`);
                textarea.value = (textarea.value ? textarea.value + '\n' : '') + sug;
            });
            container.appendChild(chip);
        });
    }
}

function removerBloco(blocoId) {
    if (confirm('⚠️ Deseja remover este bloco e todas as suas fotos?')) {
        // Remover fotos do bloco do total
        const bloco = document.getElementById(blocoId);
        const numFotos = parseInt(bloco.dataset.fotos || 0);
        totalFotos -= numFotos;
        
        // Remover do DOM
        bloco.remove();
        
        // Remover do estado
        vistoriaAtual.blocos = vistoriaAtual.blocos.filter(b => b.id !== blocoId);
        
        atualizarContadorGlobal();
    }
}

// ============================================================
// SISTEMA DE CAPTURA E PROCESSAMENTO DE FOTOS
// ============================================================

async function abrirCamera(blocoId) {
    if (!validarLimiteFotos()) return;
    
    try {
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'image/*';
        input.capture = 'environment';
        
        input.onchange = async (e) => {
            const file = e.target.files[0];
            if (file) {
                await processarFoto(file, blocoId);
            }
        };
        
        input.click();
    } catch (err) {
        alert('❌ Erro ao abrir câmera: ' + err.message);
    }
}

async function abrirGaleria(blocoId) {
    if (!validarLimiteFotos()) return;
    
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.multiple = true;
    
    input.onchange = async (e) => {
        const files = Array.from(e.target.files);
        for (const file of files) {
            if (totalFotos >= CONFIG.MAX_FOTOS) {
                alert('❌ Limite de 80 fotos atingido');
                break;
            }
            await processarFoto(file, blocoId);
        }
    };
    
    input.click();
}

function validarLimiteFotos() {
    if (totalFotos >= CONFIG.MAX_FOTOS) {
        alert('❌ LIMITE ATINGIDO\n\nMáximo de 80 fotos por vistoria.\nGere o PDF e inicie nova vistoria se necessário.');
        return false;
    }
    
    if (totalFotos >= CONFIG.ALERTA_LIMITE) {
        alert(`⚠️ ATENÇÃO\n\nVocê já tem ${totalFotos} fotos.\nLimite: ${CONFIG.MAX_FOTOS} fotos.`);
    }
    
    return true;
}

async function processarFoto(file, blocoId) {
    try {
        // 1. Ler arquivo
        const img = await carregarImagem(file);
        
        // 2. Compressão e correção EXIF
        const comprimida = await comprimirImagem(img, CONFIG.QUALIDADE_JPEG);
        
        // 3. Aplicar overlay (GPS + Data/Hora + Logo)
        const comOverlay = await aplicarOverlay(comprimida);
        
        // 4. Gerar thumbnail
        const thumbnail = await gerarThumbnail(img, CONFIG.TAMANHO_THUMBNAIL);
        
        // 5. Salvar no IndexedDB
        const fotoId = `foto-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
        const fotoData = {
            id: fotoId,
            blocoId: blocoId,
            timestamp: Date.now(),
            gps: vistoriaAtual.checkin.gps,
            fullImage: comOverlay,
            thumbnail: thumbnail
        };
        
        await salvarFoto(fotoData);
        
        // 6. Atualizar UI
        adicionarThumbnailNaUI(blocoId, fotoId, thumbnail);
        
        // 7. Atualizar contadores
        totalFotos++;
        const bloco = document.getElementById(blocoId);
        const fotosBloco = parseInt(bloco.dataset.fotos || 0) + 1;
        bloco.dataset.fotos = fotosBloco;
        document.getElementById(`${blocoId}-contador`).textContent = fotosBloco;
        atualizarContadorGlobal();
        
        // 8. Atualizar estado
        const blocoEstado = vistoriaAtual.blocos.find(b => b.id === blocoId);
        if (blocoEstado) {
            blocoEstado.fotos.push(fotoId);
        }
        
        await salvarRascunho();
        
    } catch (err) {
        console.error('Erro ao processar foto:', err);
        alert('❌ Erro ao processar foto: ' + err.message);
    }
}

function carregarImagem(file) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = reject;
            img.src = e.target.result;
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
}

async function comprimirImagem(img, qualidade) {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    
    // Manter aspect ratio, max 1280x720
    let width = img.width;
    let height = img.height;
    
    if (width > CONFIG.RESOLUCAO_CAMERA.width || height > CONFIG.RESOLUCAO_CAMERA.height) {
        const ratio = Math.min(
            CONFIG.RESOLUCAO_CAMERA.width / width,
            CONFIG.RESOLUCAO_CAMERA.height / height
        );
        width *= ratio;
        height *= ratio;
    }
    
    canvas.width = width;
    canvas.height = height;
    ctx.drawImage(img, 0, 0, width, height);
    
    return canvas.toDataURL('image/jpeg', qualidade);
}

async function aplicarOverlay(imagemBase64) {
    return new Promise((resolve) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const ctx = canvas.getContext('2d');
            
            canvas.width = img.width;
            canvas.height = img.height;
            
            // Desenhar imagem original
            ctx.drawImage(img, 0, 0);
            
            // Overlay de texto
            const endereco = document.getElementById('campo-1b').value || 'Endereço não informado';
            const dataHora = new Date().toLocaleString('pt-BR', { 
                timeZone: 'America/Sao_Paulo',
                day: '2-digit',
                month: '2-digit',
                year: 'numeric',
                hour: '2-digit',
                minute: '2-digit'
            });
            const gps = vistoriaAtual.checkin.gps;
            const gpsTexto = `GPS: ${gps.lat.toFixed(6)}, ${gps.lng.toFixed(6)} [${gps.accuracy.toFixed(0)}m]`;
            
            // Fundo semi-transparente
            ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
            ctx.fillRect(0, canvas.height - 80, canvas.width, 80);
            
            // Texto branco
            ctx.fillStyle = '#FFFFFF';
            ctx.font = 'bold 14px Arial';
            ctx.fillText(endereco, 10, canvas.height - 55);
            ctx.fillText(dataHora, 10, canvas.height - 35);
            ctx.font = '12px Arial';
            ctx.fillText(gpsTexto, 10, canvas.height - 15);
            
            resolve(canvas.toDataURL('image/jpeg', CONFIG.QUALIDADE_JPEG));
        };
        img.src = imagemBase64;
    });
}

async function gerarThumbnail(img, tamanho) {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    
    canvas.width = tamanho;
    canvas.height = tamanho;
    
    const scale = Math.max(tamanho / img.width, tamanho / img.height);
    const x = (tamanho - img.width * scale) / 2;
    const y = (tamanho - img.height * scale) / 2;
    
    ctx.drawImage(img, x, y, img.width * scale, img.height * scale);
    
    return canvas.toDataURL('image/jpeg', CONFIG.QUALIDADE_THUMBNAIL);
}

function adicionarThumbnailNaUI(blocoId, fotoId, thumbnail) {
    const container = document.getElementById(`${blocoId}-fotos`);
    
    const img = document.createElement('img');
    img.src = thumbnail;
    img.className = 'foto-thumbnail';
    img.dataset.fotoId = fotoId;
    img.title = 'Clique para visualizar';
    img.style.cssText = 'cursor: pointer; transition: transform 0.2s;';
    
    img.addEventListener('click', () => visualizarFoto(fotoId));
    
    container.appendChild(img);
}

async function visualizarFoto(fotoId) {
    const transaction = db.transaction(['fotos'], 'readonly');
    const store = transaction.objectStore('fotos');
    const foto = await store.get(fotoId);
    
    if (foto) {
        const modal = document.createElement('div');
        modal.className = 'modal';
        modal.style.display = 'flex';
        modal.innerHTML = `
            <div class="modal-content" style="max-width: 95%; max-height: 95%; overflow: auto;">
                <img src="${foto.fullImage}" style="width: 100%; height: auto;">
                <button class="btn-primary" onclick="this.parentElement.parentElement.remove()" style="margin-top: 1rem;">Fechar</button>
            </div>
        `;
        document.body.appendChild(modal);
        
        modal.addEventListener('click', (e) => {
            if (e.target === modal) modal.remove();
        });
    }
}

function atualizarContadorGlobal() {
    document.getElementById('contador-global').textContent = totalFotos;
}

