function calcularHonorarios() {
    const tipo = document.getElementById('campo-1c').value;
    const faixa = document.getElementById('campo-1f').value;
    const modalidade = document.getElementById('campo-1e').value;
    
    if (!tipo || !faixa || !modalidade) {
        return { valorBase: 0, adicionais: [], total: 0, mensagem: 'Sob análise' };
    }
    
    // Buscar valor base na tabela
    let valorBase = 0;
    try {
        valorBase = TABELA_HONORARIOS[tipo][faixa][modalidade];
    } catch (e) {
        valorBase = null;
    }
    
    if (valorBase === null || valorBase === undefined) {
        return { valorBase: 0, adicionais: [], total: 0, mensagem: 'Sob análise' };
    }
    
    // Calcular adicionais
    const adicionais = [];
    let totalAdicionais = 0;
    
    const checkboxes = {
        mobiliado: document.getElementById('add-mobiliado'),
        benfeitorias: document.getElementById('add-benfeitorias'),
        urgencia: document.getElementById('add-urgencia'),
        noturno: document.getElementById('add-noturno'),
        impedimento: document.getElementById('add-impedimento')
    };
    
    // Impedimento de acesso = 50% do valor base (ignora outros)
    if (checkboxes.impedimento?.checked) {
        const valor = valorBase * 0.5;
        return {
            valorBase: valorBase,
            adicionais: [{ nome: 'Impedimento de Acesso', percentual: 50, valor: valor }],
            total: valor,
            mensagem: null
        };
    }
    
    // Demais adicionais são cumulativos
    if (checkboxes.mobiliado?.checked) {
        const valor = valorBase * 0.25;
        adicionais.push({ nome: 'Imóvel mobiliado', percentual: 25, valor: valor });
        totalAdicionais += valor;
    }
    
    if (checkboxes.benfeitorias?.checked) {
        const valor = valorBase * 0.25;
        adicionais.push({ nome: 'Terreno com benfeitorias/estruturas', percentual: 25, valor: valor });
        totalAdicionais += valor;
    }
    
    if (checkboxes.urgencia?.checked) {
        const valor = valorBase * 0.20;
        adicionais.push({ nome: 'Urgência (entrega em 24h)', percentual: 20, valor: valor });
        totalAdicionais += valor;
    }
    
    if (checkboxes.noturno?.checked) {
        const valor = valorBase * 0.30;
        adicionais.push({ nome: 'Vistoria noturna (18h às 08h)', percentual: 30, valor: valor });
        totalAdicionais += valor;
    }
    
    return {
        valorBase: valorBase,
        adicionais: adicionais,
        total: valorBase + totalAdicionais,
        mensagem: null
    };
}

// ============================================================
// GERAÇÃO DE PDF
// ============================================================

async function gerarPDF() {
    // Validações
    if (!vistoriaAtual.checkin) {
        alert('❌ Check-in não realizado');
        return;
    }
    
    if (!validarCamposObrigatorios()) {
        return;
    }
    
    if (totalFotos === 0) {
        alert('❌ Capture pelo menos 1 foto antes de gerar o PDF');
        return;
    }
    
    if (vistoriaAtual.assinaturas.length === 0) {
        alert('❌ Adicione pelo menos 1 assinatura de cliente');
        return;
    }
    
    // Verificar espaço
    if (!await verificarEspacoParaPDF(totalFotos)) {
        return;
    }
    
    // Mostrar modal de progresso
    const modal = document.getElementById('pdf-progress-modal');
    modal.style.display = 'flex';
    
    try {
        await gerarPDFComProgresso();
        modal.style.display = 'none';
        alert('✅ PDF gerado com sucesso!');
    } catch (err) {
        modal.style.display = 'none';
        alert('❌ Erro ao gerar PDF: ' + err.message);
        console.error(err);
    }
}

function validarCamposObrigatorios() {
    const campos = [
        { id: 'campo-1b', nome: 'Endereço do Imóvel' },
        { id: 'campo-1c', nome: 'Tipo de Imóvel' },
        { id: 'campo-1e', nome: 'Modalidade de Vistoria' },
        { id: 'campo-1f', nome: 'Faixa de Metragem' }
    ];
    
    for (const campo of campos) {
        const valor = document.getElementById(campo.id).value;
        if (!valor) {
            alert(`❌ Campo obrigatório não preenchido:\n${campo.nome}`);
            document.getElementById(campo.id).focus();
            return false;
        }
    }
    
    return true;
}

async function verificarEspacoParaPDF(totalFotos) {
    if (!navigator.storage || !navigator.storage.estimate) return true;
    
    const estimate = await navigator.storage.estimate();
    const disponivelMB = (estimate.quota - estimate.usage) / 1024 / 1024;
    const necessarioMB = totalFotos * 0.3; // 300KB por foto
    
    if (disponivelMB < necessarioMB) {
        alert(`❌ ESPAÇO INSUFICIENTE\n\nNecessário: ${necessarioMB.toFixed(1)}MB\nDisponível: ${disponivelMB.toFixed(1)}MB\n\nLibere espaço antes de gerar PDF.`);
        return false;
    }
    
    return true;
}

async function gerarPDFComProgresso() {
    const { jsPDF } = window.jspdf;
    const pdf = new jsPDF('p', 'mm', 'a4');
    
    let yPos = 25;
    const margin = { top: 25, right: 20, bottom: 25, left: 20 };
    const pageHeight = 297;
    
    // PÁGINA 1 - CABEÇALHO E SEÇÃO 1
    
    // Logo no topo (centralizado)
    pdf.setFontSize(16);
    pdf.setFont('helvetica', 'bold');
    pdf.setTextColor(212, 175, 55); // Dourado
    pdf.text(CONFIG.VISTORIADOR.nome, 105, yPos, { align: 'center' });
    yPos += 7;
    
    pdf.setFontSize(10);
    pdf.setFont('helvetica', 'normal');
    pdf.text('Serviços Técnicos Imobiliários', 105, yPos, { align: 'center' });
    yPos += 5;
    pdf.text(`CRECI ${CONFIG.VISTORIADOR.creci}`, 105, yPos, { align: 'center' });
    yPos += 15;
    
    // SEÇÃO 1: DADOS INICIAIS
    pdf.setFontSize(14);
    pdf.setFont('helvetica', 'bold');
    pdf.setTextColor(212, 175, 55);
    pdf.text('1. DADOS INICIAIS', margin.left, yPos);
    yPos += 8;
    
    pdf.setFontSize(10);
    pdf.setTextColor(0, 0, 0);
    pdf.setFont('helvetica', 'normal');
    
    const dadosSecao1 = obterDadosSecao1();
    
    pdf.text(`1a. ${dadosSecao1['1a'] || 'N/A'}`, margin.left, yPos);
    yPos += 6;
    pdf.text(`1b. Endereço: ${dadosSecao1['1b']}`, margin.left, yPos);
    yPos += 6;
    pdf.text(`1c. Tipo: ${dadosSecao1['1c']}`, margin.left, yPos);
    yPos += 6;
    pdf.text(`1d. Tipologia: ${dadosSecao1['1d'] || 'N/A'}`, margin.left, yPos);
    yPos += 6;
    pdf.text(`1e. Modalidade: ${dadosSecao1['1e']}`, margin.left, yPos);
    yPos += 6;
    pdf.text(`1f. Metragem: ${dadosSecao1['1f']}`, margin.left, yPos);
    yPos += 12;
    
    // SEÇÃO 2: OBSERVAÇÕES POR LOCAL
    if (yPos > pageHeight - 40) {
        pdf.addPage();
        yPos = margin.top;
    }
    
    pdf.setFontSize(14);
    pdf.setFont('helvetica', 'bold');
    pdf.setTextColor(212, 175, 55);
    pdf.text('2. OBSERVAÇÕES POR LOCAL', margin.left, yPos);
    yPos += 10;
    
    pdf.setFontSize(10);
    pdf.setTextColor(0, 0, 0);
    pdf.setFont('helvetica', 'normal');
    
    // Processar cada bloco
    const blocos = document.querySelectorAll('.bloco-observacao');
    let totalFotosProcessadas = 0;
    
    for (const bloco of blocos) {
        const blocoId = bloco.id;
        const local = document.getElementById(`${blocoId}-local`).value;
        const obs = document.getElementById(`${blocoId}-obs`).value;
        const detalhes = document.getElementById(`${blocoId}-detalhes`).value;
        
        if (yPos > pageHeight - 30) {
            pdf.addPage();
            yPos = margin.top;
        }
        
        pdf.setFont('helvetica', 'bold');
        pdf.text(`${SECAO_2_GLOSSARIOS[dadosSecao1['1c']].label} ${local}`, margin.left, yPos);
        yPos += 6;
        
        pdf.setFont('helvetica', 'normal');
        if (obs) {
            pdf.text(`Observações: ${obs}`, margin.left, yPos);
            yPos += 6;
        }
        if (detalhes) {
            const linhas = pdf.splitTextToSize(detalhes, 170);
            pdf.text(linhas, margin.left, yPos);
            yPos += linhas.length * 5;
        }
        yPos += 5;
        
        // Fotos do bloco
        const fotosBloco = bloco.querySelector('.fotos-container').children;
        for (const thumbnail of fotosBloco) {
            const fotoId = thumbnail.dataset.fotoId;
            
            // Atualizar progresso
            totalFotosProcessadas++;
            document.getElementById('progress-fill').style.width = `${(totalFotosProcessadas / totalFotos) * 100}%`;
            document.getElementById('progress-text').textContent = `Processando foto ${totalFotosProcessadas}...`;
            document.getElementById('progress-stats').textContent = `${totalFotosProcessadas} de ${totalFotos} fotos`;
            
            // Buscar foto completa do IndexedDB
            const transaction = db.transaction(['fotos'], 'readonly');
            const store = transaction.objectStore('fotos');
            const foto = await store.get(fotoId);
            
            if (foto) {
                const fotoHeight = 100;
                
                if (yPos + fotoHeight > pageHeight - margin.bottom) {
                    pdf.addPage();
                    yPos = margin.top;
                }
                
                pdf.addImage(foto.fullImage, 'JPEG', margin.left, yPos, 170, fotoHeight);
                yPos += fotoHeight + 5;
            }
            
            // Pequena pausa para não travar a UI
            await new Promise(r => setTimeout(r, 50));
        }
        
        yPos += 5;
    }
    
    // SEÇÃO 3: ASSINATURAS
    pdf.addPage();
    yPos = margin.top;
    
    pdf.setFontSize(14);
    pdf.setFont('helvetica', 'bold');
    pdf.setTextColor(212, 175, 55);
    pdf.text('3. ASSINATURAS', margin.left, yPos);
    yPos += 10;
    
    // Assinatura do vistoriador
    pdf.setFontSize(10);
    pdf.setTextColor(0, 0, 0);
    pdf.setFont('helvetica', 'normal');
    pdf.text('3a. Vistoriador:', margin.left, yPos);
    yPos += 8;
    
    pdf.setFontSize(20);
    pdf.setFont('times', 'italic');
    pdf.setTextColor(0, 51, 102); // Azul assinatura
    pdf.text(CONFIG.VISTORIADOR.nome, margin.left, yPos);
    yPos += 15;
    
    // Assinaturas dos clientes
    pdf.setFontSize(10);
    pdf.setFont('helvetica', 'normal');
    pdf.setTextColor(0, 0, 0);
    
    for (const assinatura of vistoriaAtual.assinaturas) {
        const qualificacao = document.getElementById(`${assinatura.id}-qual`).value;
        
        if (yPos > pageHeight - 60) {
            pdf.addPage();
            yPos = margin.top;
        }
        
        pdf.text(`Qualificação: ${qualificacao || 'Não informada'}`, margin.left, yPos);
        yPos += 8;
        
        if (assinatura.assinatura && !assinatura.assinatura.isEmpty()) {
            const assinaturaData = assinatura.assinatura.toDataURL();
            pdf.addImage(assinaturaData, 'PNG', margin.left, yPos, 80, 30);
            yPos += 35;
        }
    }
    
    // Frase de segurança jurídica
    yPos += 10;
    pdf.setFontSize(9);
    pdf.setFont('helvetica', 'bold');
    pdf.text('⚖️ CERTIFICAÇÃO PERICIAL', margin.left, yPos);
    yPos += 6;
    
    pdf.setFont('helvetica', 'normal');
    const fraseSeguranca = 'Este laudo de vistoria é um documento pericial inviolável, certificado pela identificação do Vistoriador Emilio Paulo Granata, contendo evidências fotográficas gravadas com coordenadas geográficas de precisão (GPS) e carimbo de data/hora, assegurando a integridade e a veracidade das condições do imóvel no ato da inspeção.';
    const linhas = pdf.splitTextToSize(fraseSeguranca, 170);
    pdf.text(linhas, margin.left, yPos);
    yPos += linhas.length * 5;
    
    // SEÇÃO 4: HONORÁRIOS (apenas no PDF)
    pdf.addPage();
    yPos = margin.top;
    
    pdf.setFontSize(14);
    pdf.setFont('helvetica', 'bold');
    pdf.setTextColor(212, 175, 55);
    pdf.text('4. HONORÁRIOS (EM R$)', margin.left, yPos);
    yPos += 10;
    
    const honorarios = calcularHonorarios();
    
    pdf.setFontSize(10);
    pdf.setTextColor(0, 0, 0);
    pdf.setFont('helvetica', 'normal');
    
    if (honorarios.mensagem) {
        pdf.text(honorarios.mensagem, margin.left, yPos);
    } else {
        pdf.text(`Valor Base: R$ ${honorarios.valorBase.toFixed(2)}`, margin.left, yPos);
        yPos += 6;
        pdf.text(`(${dadosSecao1['1c']}, ${dadosSecao1['1f']}, ${dadosSecao1['1e']})`, margin.left, yPos);
        yPos += 10;
        
        if (honorarios.adicionais.length > 0) {
            pdf.text('Adicionais por Escopo:', margin.left, yPos);
            yPos += 6;
            
            for (const ad of honorarios.adicionais) {
                pdf.text(`☑ ${ad.nome}: +${ad.percentual}% ........ R$ ${ad.valor.toFixed(2)}`, margin.left + 5, yPos);
                yPos += 6;
            }
            yPos += 5;
        }
        
        pdf.setFont('helvetica', 'bold');
        pdf.text('─'.repeat(70), margin.left, yPos);
        yPos += 6;
        pdf.setFontSize(12);
        pdf.text(`VALOR TOTAL: R$ ${honorarios.total.toFixed(2)}`, margin.left, yPos);
        pdf.setFontSize(10);
        yPos += 6;
        pdf.text('─'.repeat(70), margin.left, yPos);
    }
    
    // Rodapé fixo em todas as páginas
    const totalPages = pdf.internal.getNumberOfPages();
    for (let i = 1; i <= totalPages; i++) {
        pdf.setPage(i);
        
        pdf.setFontSize(8);
        pdf.setTextColor(100, 100, 100);
        pdf.setFont('helvetica', 'normal');
        pdf.text('Este documento é inviolável e auditável digitalmente. Prova Pericial Garantida.', 105, 287, { align: 'center' });
        
        pdf.setFontSize(9);
        pdf.text(`Pág. ${String(i).padStart(2, '0')} de ${String(totalPages).padStart(2, '0')}`, 190, 287, { align: 'right' });
    }
    
    // Salvar PDF
    const nomeArquivo = gerarNomeArquivo();
    pdf.save(nomeArquivo);
    
    document.getElementById('progress-text').textContent = 'PDF gerado com sucesso!';
}

function obterDadosSecao1() {
    return {
        '1a': document.getElementById('campo-1a').value,
        '1b': document.getElementById('campo-1b').value,
        '1c': document.getElementById('campo-1c').value,
        '1d': document.getElementById('campo-1d').value,
        '1e': document.getElementById('campo-1e').value,
        '1f': document.getElementById('campo-1f').value
    };
}

function obterAdicionais() {
    return {
        mobiliado: document.getElementById('add-mobiliado')?.checked || false,
        benfeitorias: document.getElementById('add-benfeitorias')?.checked || false,
        urgencia: document.getElementById('add-urgencia')?.checked || false,
        noturno: document.getElementById('add-noturno')?.checked || false,
        impedimento: document.getElementById('add-impedimento')?.checked || false
    };
}

function gerarNomeArquivo() {
    const modalidade = document.getElementById('campo-1e').value;
    const tipo = modalidade.includes('entrada') ? 'ENT' : 
                 modalidade.includes('saída') ? 'SAI' : 
                 'VIS';
    
    const endereco = document.getElementById('campo-1b').value
        .replace(/[^a-zA-Z0-9]/g, '_')
        .substring(0, 30);
    
    const data = new Date().toISOString().split('T')[0];
    
    return `${tipo}_${endereco}_${data}.pdf`;
}

