async function verificarEspacoDisponivel() {
    if (!navigator.storage || !navigator.storage.estimate) return true;
    
    const estimate = await navigator.storage.estimate();
    const usadoMB = (estimate.usage / 1024 / 1024).toFixed(1);
    const disponivelMB = (estimate.quota / 1024 / 1024).toFixed(1);
    const percentual = ((estimate.usage / estimate.quota) * 100).toFixed(1);
    
    if (percentual > 70) {
        console.warn(`⚠️ Espaço limitado: ${percentual}% usado (${usadoMB}MB de ${disponivelMB}MB)`);
    }
    
    if (percentual > 85) {
        alert(`⚠️ ESPAÇO LIMITADO (${percentual}%)\n\nUsado: ${usadoMB}MB de ${disponivelMB}MB\n\nRecomendado:\n• Gere PDFs das vistorias antigas\n• Limpe vistorias finalizadas`);
        return false;
    }
    
    return true;
}

