// ============================================================
// MELHORIA #1: Validação de Luminosidade
// ============================================================
async function validarLuminosidade() {
    return new Promise((resolve) => {
        const video = document.createElement('video');
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        
        navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } })
            .then(stream => {
                video.srcObject = stream;
                video.play();
                
                setTimeout(() => {
                    canvas.width = video.videoWidth;
                    canvas.height = video.videoHeight;
                    ctx.drawImage(video, 0, 0);
                    
                    const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
                    const data = imageData.data;
                    let luminosidadeMedia = 0;
                    
                    for (let i = 0; i < data.length; i += 4) {
                        luminosidadeMedia += (data[i] + data[i+1] + data[i+2]) / 3;
                    }
                    
                    luminosidadeMedia /= (data.length / 4);
                    stream.getTracks().forEach(track => track.stop());
                    
                    if (luminosidadeMedia < CONFIG_V2.LUMINOSIDADE_MIN) {
                        const usar = confirm(`⚠️ LUMINOSIDADE BAIXA (${Math.round(luminosidadeMedia)}/255)\n\nAmbiente muito escuro. Foto pode sair ruim.\n\nContinuar mesmo assim?`);
                        resolve(usar);
                    } else {
                        resolve(true);
                    }
                }, 500);
            })
            .catch(() => resolve(true));
    });
}

// ============================================================
// MELHORIA #2: Flash Contínuo
// ============================================================
async function ativarFlash(stream) {
    try {
        const track = stream.getVideoTracks()[0];
        const capabilities = track.getCapabilities();
        
        if (capabilities.torch) {
            await track.applyConstraints({
                advanced: [{ torch: true }]
            });
            flashAtivo = true;
            console.log('🔦 Flash ativado');
        }
    } catch (error) {
        console.warn('Flash não suportado:', error);
    }
}

async function desativarFlash(stream) {
    try {
        const track = stream.getVideoTracks()[0];
        await track.applyConstraints({
            advanced: [{ torch: false }]
        });
        flashAtivo = false;
        console.log('🔦 Flash desativado');
    } catch (error) {
        console.warn('Erro ao desativar flash:', error);
    }
}

