// ============================================================
// MELHORIA #7: Anotações de Voz
// ============================================================
function iniciarGravacaoVoz(blocoId) {
    if (!('webkitSpeechRecognition' in window) && !('SpeechRecognition' in window)) {
        alert('❌ Reconhecimento de voz não suportado neste navegador');
        return;
    }
    
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    const recognition = new SpeechRecognition();
    
    recognition.lang = 'pt-BR';
    recognition.continuous = false;
    recognition.interimResults = false;
    
    const indicador = document.getElementById('voz-indicador');
    if (indicador) indicador.style.display = 'flex';
    
    recognition.onresult = (event) => {
        const transcript = event.results[0][0].transcript;
        const textarea = document.getElementById(`${blocoId}-detalhes`);
        if (textarea) {
            textarea.value = (textarea.value ? textarea.value + '\n' : '') + transcript;
        }
        if (indicador) indicador.style.display = 'none';
    };
    
    recognition.onerror = () => {
        if (indicador) indicador.style.display = 'none';
        alert('❌ Erro no reconhecimento de voz');
    };
    
    recognition.onend = () => {
        if (indicador) indicador.style.display = 'none';
    };
    
    recognition.start();
}

