async function salvarComoTemplate() {
    const nome = prompt('Nome do template:');
    if (!nome) return;
    
    const template = {
        id: Date.now(),
        nome: nome,
        timestamp: Date.now(),
        dados: {
            '1a': document.getElementById('campo-1a')?.value || '',
            '1b': document.getElementById('campo-1b')?.value || '',
            '1c': document.getElementById('campo-1c')?.value || '',
            '1d': document.getElementById('campo-1d')?.value || '',
            '1e': document.getElementById('campo-1e')?.value || '',
            '1f': document.getElementById('campo-1f')?.value || ''
        }
    };
    
    const templates = JSON.parse(localStorage.getItem('templates') || '[]');
    templates.push(template);
    localStorage.setItem('templates', JSON.stringify(templates));
    
    alert('✅ Template salvo com sucesso!');
}

async function carregarTemplate() {
    const templates = JSON.parse(localStorage.getItem('templates') || '[]');
    
    if (templates.length === 0) {
        alert('Nenhum template salvo');
        return;
    }
    
    const modal = document.getElementById('templates-modal');
    const lista = document.getElementById('templates-lista');
    
    if (!modal || !lista) return;
    
    lista.innerHTML = '';
    
    templates.forEach(t => {
        const div = document.createElement('div');
        div.className = 'template-item';
        div.innerHTML = `
            <h4>${t.nome}</h4>
            <p>Criado em: ${new Date(t.timestamp).toLocaleDateString('pt-BR')}</p>
        `;
        div.onclick = () => {
            Object.keys(t.dados).forEach(key => {
                const campo = document.getElementById(`campo-${key}`);
                if (campo) campo.value = t.dados[key];
            });
            fecharTemplates();
            alert('✅ Template carregado!');
        };
        lista.appendChild(div);
    });
    
    modal.style.display = 'flex';
}

function fecharTemplates() {
    const modal = document.getElementById('templates-modal');
    if (modal) modal.style.display = 'none';
}

