// MELHORIA #10: Histórico por Imóvel
// ============================================================
async function verHistorico() {
    const endereco = document.getElementById('campo-1b')?.value;
    if (!endereco) {
        alert('Informe o endereço do imóvel primeiro');
        return;
    }
    
    try {
        const transaction = db.transaction(['finalizadas'], 'readonly');
        const store = transaction.objectStore('finalizadas');
        const todas = await new Promise((resolve, reject) => {
            const request = store.getAll();
            request.onsuccess = () => resolve(request.result || []);
            request.onerror = () => reject(request.error);
        });
        
        const historico = todas.filter(v => 
            v.endereco && v.endereco.toLowerCase().includes(endereco.toLowerCase())
        );
        
        const modal = document.getElementById('historico-modal');
        const lista = document.getElementById('historico-lista');
        
        if (!modal || !lista) return;
        
        lista.innerHTML = '';
        
        if (historico.length === 0) {
            lista.innerHTML = '<p>Nenhuma vistoria anterior encontrada para este endereço</p>';
        } else {
            historico.forEach(h => {
                const div = document.createElement('div');
                div.className = 'historico-item';
                div.innerHTML = `
                    <h4>${h.modalidade || 'Vistoria'}</h4>
                    <p>Data: ${new Date(h.timestamp).toLocaleDateString('pt-BR')}</p>
                    <p>Fotos: ${h.totalFotos || 0}</p>
                `;
                lista.appendChild(div);
            });
        }
        
        modal.style.display = 'flex';
    } catch (error) {
        console.error('Erro ao buscar histórico:', error);
        alert('Erro ao buscar histórico');
    }
}

function fecharHistorico() {
    const modal = document.getElementById('historico-modal');
    if (modal) modal.style.display = 'none';
}

