// ============================================================
// MELHORIA #14: Criptografia AES-256
// ============================================================
function criptografar(dados) {
    if (typeof CryptoJS === 'undefined') {
        console.warn('CryptoJS não disponível');
        return JSON.stringify(dados);
    }
    
    if (!CONFIG_V2.CRIPTOGRAFIA_ATIVADA) {
        return JSON.stringify(dados);
    }
    
    try {
        const encrypted = CryptoJS.AES.encrypt(
            JSON.stringify(dados),
            CONFIG_V2.CHAVE_CRIPTOGRAFIA
        ).toString();
        return encrypted;
    } catch (error) {
        console.error('Erro ao criptografar:', error);
        return JSON.stringify(dados);
    }
}

function descriptografar(dadosCriptografados) {
    if (typeof CryptoJS === 'undefined') {
        console.warn('CryptoJS não disponível');
        try {
            return JSON.parse(dadosCriptografados);
        } catch {
            return dadosCriptografados;
        }
    }
    
    if (!CONFIG_V2.CRIPTOGRAFIA_ATIVADA) {
        try {
            return JSON.parse(dadosCriptografados);
        } catch {
            return dadosCriptografados;
        }
    }
    
    try {
        const bytes = CryptoJS.AES.decrypt(
            dadosCriptografados,
            CONFIG_V2.CHAVE_CRIPTOGRAFIA
        );
        const decrypted = bytes.toString(CryptoJS.enc.Utf8);
        return JSON.parse(decrypted);
    } catch (error) {
        console.error('Erro ao descriptografar:', error);
        return null;
    }
}

// ============================================================
// MELHORIA #15: Hash SHA-256 + QR Code
// ============================================================
async function gerarHashSHA256(pdfBlob) {
    try {
        const arrayBuffer = await pdfBlob.arrayBuffer();
        const hashBuffer = await crypto.subtle.digest('SHA-256', arrayBuffer);
        const hashArray = Array.from(new Uint8Array(hashBuffer));
        const hashHex = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
        return hashHex;
    } catch (error) {
        console.error('Erro ao gerar hash:', error);
        return null;
    }
}

function adicionarQRCodeAoPDF(pdf, hash) {
    if (typeof QRCode === 'undefined') {
        console.warn('QRCode.js não disponível');
        return;
    }
    
    try {
        const canvas = document.createElement('canvas');
        const qr = new QRCode(canvas, {
            text: `https://verify.vistorias.app?hash=${hash}`,
            width: 80,
            height: 80
        });
        
        // Adicionar QR Code ao PDF (última página, canto inferior direito)
        const pageCount = pdf.internal.getNumberOfPages();
        pdf.setPage(pageCount);
        
        const qrDataURL = canvas.toDataURL('image/png');
        pdf.addImage(qrDataURL, 'PNG', 185, 267, 20, 20);
        
        console.log('✅ QR Code adicionado ao PDF');
    } catch (error) {
        console.error('Erro ao adicionar QR Code:', error);
    }
}

