// ============================================================
// MELHORIA #22: Correção EXIF
// ============================================================
function corrigirOrientacaoEXIF(img, orientation) {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    
    // Definir tamanho do canvas baseado na orientação
    if (orientation > 4) {
        canvas.width = img.height;
        canvas.height = img.width;
    } else {
        canvas.width = img.width;
        canvas.height = img.height;
    }
    
    // Aplicar transformações baseadas na orientação EXIF
    switch (orientation) {
        case 2:
            ctx.transform(-1, 0, 0, 1, canvas.width, 0);
            break;
        case 3:
            ctx.transform(-1, 0, 0, -1, canvas.width, canvas.height);
            break;
        case 4:
            ctx.transform(1, 0, 0, -1, 0, canvas.height);
            break;
        case 5:
            ctx.transform(0, 1, 1, 0, 0, 0);
            break;
        case 6:
            ctx.transform(0, 1, -1, 0, canvas.height, 0);
            break;
        case 7:
            ctx.transform(0, -1, -1, 0, canvas.height, canvas.width);
            break;
        case 8:
            ctx.transform(0, -1, 1, 0, 0, canvas.width);
            break;
        default:
            break;
    }
    
    ctx.drawImage(img, 0, 0);
    return canvas.toDataURL('image/jpeg', CONFIG.QUALIDADE_JPEG);
}

